	name = "Bank to Patch",
	description = "Kijkt in je bank en maakt een farm run met route, zaden, compost en teleports",
	tags = {"farming", "herb", "tree", "route", "teleport", "bank", "planner"}
)
public class FarmPlannerPlugin extends Plugin
{
	private static final int INVENTORY = InventoryID.INV;
	private static final int EQUIPMENT = InventoryID.WORN;
	private static final int BANK = InventoryID.BANK;

	private static final int PLANT_DISTANCE = 4;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private FarmPlannerConfig config;

	@Inject
	private BankHighlightOverlay bankOverlay;

	@Inject
	private PatchOverlay patchOverlay;

	@Inject
	private TeleportChoiceOverlay teleportOverlay;

	private FarmPlannerPanel panel;
	private NavigationButton navButton;

	/** Laatst bekende inhoud per container. Alleen op de client thread gebruiken. */
	private final Map<Integer, Item[]> containers = new HashMap<>();
	/** Farming patches die nu in de wereld geladen zijn. Alleen op de client thread. */
	private final Set<GameObject> patchObjects = new HashSet<>();
	/** Widgets (dialoogopties, spreuken) die nu gehighlight moeten worden. */
	private List<Widget> highlightedWidgets = Collections.emptyList();

	private volatile boolean bankSeen;
	private volatile FarmPlan plan;
	/** Per route-stap: gedaan (groen) of nog niet. */
	private volatile boolean[] done = new boolean[0];
	private int lastSeedCount = -1;
	private WorldPoint ourHintArrow;
	private int tickCounter;

	@Provides
	FarmPlannerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FarmPlannerConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new FarmPlannerPanel(this);
		navButton = NavigationButton.builder()
			.tooltip("Bank to Patch")
			.icon(createIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(bankOverlay);
		overlayManager.add(patchOverlay);
		overlayManager.add(teleportOverlay);

		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				store(INVENTORY, client.getItemContainer(INVENTORY));
				store(EQUIPMENT, client.getItemContainer(EQUIPMENT));
				store(BANK, client.getItemContainer(BANK));
				scanScene();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(bankOverlay);
		overlayManager.remove(patchOverlay);
		overlayManager.remove(teleportOverlay);
		clientThread.invokeLater(this::clearOurHintArrow);
		containers.clear();
		patchObjects.clear();
		highlightedWidgets = Collections.emptyList();
		bankSeen = false;
		plan = null;
	}

	// ------------------------------------------------------------------ items

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == INVENTORY || id == EQUIPMENT || id == BANK)
		{
			store(id, event.getItemContainer());
		}
		if (id == INVENTORY)
		{
			checkSeedPlanted(event.getItemContainer());
		}
	}

	private void store(int id, ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		containers.put(id, container.getItems());
		if (id == BANK)
		{
			bankSeen = true;
			SwingUtilities.invokeLater(() -> panel.setBankSeen(true));
		}
	}

	/**
	 * Als het zaad van de huidige stap minder wordt terwijl je naast een patch staat,
	 * heb je geplant: ga door naar de volgende stap.
	 */
	private void checkSeedPlanted(ItemContainer inventory)
	{
		FarmPlan.Step step = getCurrentStep();
		if (step == null || inventory == null)
		{
			lastSeedCount = -1;
			return;
		}
		int now = inventory.count(step.getSeedItemId());
		if (lastSeedCount >= 0 && now < lastSeedCount && isNearPatch())
		{
			lastSeedCount = -1;
			changeStep(1);
			return;
		}
		lastSeedCount = now;
	}

	private boolean isNearPatch()
	{
		Player p = client.getLocalPlayer();
		FarmPlan current = plan;
		if (p == null || current == null)
		{
			return false;
		}
		WorldPoint me = p.getWorldLocation();
		Set<Integer> ids = PatchIds.forRun(current.getRunType());
		for (GameObject o : patchObjects)
		{
			if (ids.contains(o.getId()) && o.getWorldLocation().distanceTo(me) <= PLANT_DISTANCE)
			{
				return true;
			}
		}
		return false;
	}

	// ------------------------------------------------------------------ plan

	/** Wordt aangeroepen door de knop in het paneel. */
	void requestPlan(RunType type)
	{
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				SwingUtilities.invokeLater(() -> panel.showMessage("Log eerst in."));
				return;
			}
			if (!bankSeen)
			{
				SwingUtilities.invokeLater(() -> panel.showMessage(
					"Open eerst je bank één keer, zodat de plugin kan zien wat je hebt."));
				return;
			}

			OwnedItems owned = collectOwnedItems();
			int farming = client.getRealSkillLevel(Skill.FARMING);
			int magic = client.getBoostedSkillLevel(Skill.MAGIC);
			PlanOptions options = new PlanOptions(
				config.useSpells(),
				config.houseInHosidius(),
				config.includeTrollheim(),
				config.includeLletya(),
				Math.max(0, config.coinsPerTree()),
				config.payProtection());

			FarmPlan newPlan = PlanBuilder.build(type, owned, farming, magic, options);
			done = new boolean[newPlan.getActiveSteps().size()];
			plan = newPlan;
			lastSeedCount = -1;
			checkSeedPlanted(client.getItemContainer(INVENTORY));
			refreshPanel();
		});
	}

	private void refreshPanel()
	{
		FarmPlan current = plan;
		if (current == null)
		{
			return;
		}
		boolean[] snapshot = done.clone();
		SwingUtilities.invokeLater(() -> panel.showPlan(current, snapshot));
	}

	/** Klik op een stap in het paneel: gedaan / niet gedaan. */
	void toggleDone(int index)
	{
		boolean[] d = done;
		if (index < 0 || index >= d.length)
		{
			return;
		}
		d[index] = !d[index];
		afterStepChange();
	}

	private void afterStepChange()
	{
		clientThread.invokeLater(() ->
		{
			lastSeedCount = -1;
			checkSeedPlanted(client.getItemContainer(INVENTORY));
		});
		refreshPanel();
	}

	void clearPlan()
	{
		plan = null;
		clientThread.invokeLater(() ->
		{
			clearOurHintArrow();
			highlightedWidgets = Collections.emptyList();
		});
	}

	/**
	 * +1 = huidige stap afvinken (gedaan, groen).
	 * -1 = laatst afgevinkte stap weer open zetten.
	 */
	void changeStep(int delta)
	{
		boolean[] d = done;
		if (plan == null || d.length == 0)
		{
			return;
		}
		if (delta > 0)
		{
			int i = currentIndex();
			if (i >= 0)
			{
				d[i] = true;
			}
		}
		else
		{
			for (int i = d.length - 1; i >= 0; i--)
			{
				if (d[i])
				{
					d[i] = false;
					break;
				}
			}
		}
		afterStepChange();
	}

	/** Index van de eerste stap die nog niet gedaan is, of -1 als alles klaar is. */
	private int currentIndex()
	{
		boolean[] d = done;
		for (int i = 0; i < d.length; i++)
		{
			if (!d[i])
			{
				return i;
			}
		}
		return -1;
	}

	/** Huidige stap, of null als er geen plan is of de run klaar is. */
	FarmPlan.Step getCurrentStep()
	{
		FarmPlan current = plan;
		if (current == null)
		{
			return null;
		}
		List<FarmPlan.Step> steps = current.getActiveSteps();
		int i = currentIndex();
		return i >= 0 && i < steps.size() ? steps.get(i) : null;
	}

	FarmPlan getPlan()
	{
		return plan;
	}

	/** Moet op de client thread draaien (ItemManager). */
	private OwnedItems collectOwnedItems()
	{
		OwnedItems owned = new OwnedItems();
		for (Item[] items : containers.values())
		{
			for (Item item : items)
			{
				if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
				{
					continue;
				}
				ItemComposition comp = itemManager.getItemComposition(item.getId());
				if (comp.getPlaceholderTemplateId() != -1)
				{
					continue; // bank placeholder
				}
				int realId = comp.getNote() != -1 ? comp.getLinkedNoteId() : item.getId();
				owned.add(realId, comp.getName(), item.getQuantity());
			}
		}
		return owned;
	}

	// ------------------------------------------------------------------ patches in de wereld

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		if (PatchIds.isAnyPatch(event.getGameObject().getId()))
		{
			patchObjects.add(event.getGameObject());
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		patchObjects.remove(event.getGameObject());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			patchObjects.clear();
		}
	}

	private void scanScene()
	{
		patchObjects.clear();
		Scene scene = client.getTopLevelWorldView().getScene();
		Tile[][][] tiles = scene.getTiles();
		for (Tile[][] plane : tiles)
		{
			for (Tile[] row : plane)
			{
				for (Tile tile : row)
				{
					if (tile == null || tile.getGameObjects() == null)
					{
						continue;
					}
					for (GameObject o : tile.getGameObjects())
					{
						if (o != null && PatchIds.isAnyPatch(o.getId()))
						{
							patchObjects.add(o);
						}
					}
				}
			}
		}
	}

	/** Patches van de huidige run die nu in beeld zijn. */
	List<GameObject> getVisiblePatches()
	{
		FarmPlan current = plan;
		if (current == null)
		{
			return Collections.emptyList();
		}
		Set<Integer> ids = PatchIds.forRun(current.getRunType());
		List<GameObject> result = new ArrayList<>();
		for (GameObject o : patchObjects)
		{
			if (ids.contains(o.getId()))
			{
				result.add(o);
			}
		}
		return result;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		updateHintArrow();
	}

	private void updateHintArrow()
	{
		Player p = client.getLocalPlayer();
		if (!config.hintArrow() || getCurrentStep() == null || p == null)
		{
			clearOurHintArrow();
			return;
		}
		WorldPoint me = p.getWorldLocation();
		GameObject nearest = null;
		int best = Integer.MAX_VALUE;
		for (GameObject o : getVisiblePatches())
		{
			int d = o.getWorldLocation().distanceTo(me);
			if (d < best)
			{
				best = d;
				nearest = o;
			}
		}
		if (nearest == null || best <= 2)
		{
			clearOurHintArrow();
			return;
		}
		// Niet de pijl van een andere plugin (bijv. Quest Helper) overschrijven.
		boolean arrowIsOurs = ourHintArrow != null && ourHintArrow.equals(client.getHintArrowPoint());
		if (client.hasHintArrow() && !arrowIsOurs)
		{
			return;
		}
		WorldPoint target = nearest.getWorldLocation();
		if (!target.equals(ourHintArrow))
		{
			client.setHintArrow(target);
			ourHintArrow = target;
		}
	}

	private void clearOurHintArrow()
	{
		if (ourHintArrow != null && client.hasHintArrow() && ourHintArrow.equals(client.getHintArrowPoint()))
		{
			client.clearHintArrow();
		}
		ourHintArrow = null;
	}

	// ------------------------------------------------------------------ teleport-keuze highlighten

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		FarmPlan.Step step = getCurrentStep();
		if (!config.highlightTeleport() || step == null || step.getTeleportOption() == null)
		{
			return;
		}
		TeleportOption t = step.getTeleportOption();
		MenuEntry entry = event.getMenuEntry();
		String option = Text.removeTags(entry.getOption());
		String target = Text.removeTags(entry.getTarget());

		Color color = config.highlightColor();
		if (t.getKind() == TeleportOption.Kind.SPELL)
		{
			if (option.equalsIgnoreCase("Cast") && target.equalsIgnoreCase(t.getSpellName()))
			{
				entry.setOption(ColorUtil.wrapWithColorTag(option, color));
			}
			return;
		}

		// Keuze in een teleport-venster (bijv. "Xeric's Glade", "Burthorpe") als menu-optie of -target.
		for (String wanted : t.getDialogOptions())
		{
			if (matchesChoice(option, wanted))
			{
				entry.setOption(ColorUtil.wrapWithColorTag(option, color));
				return;
			}
			if (matchesChoice(target, wanted))
			{
				entry.setTarget(ColorUtil.wrapWithColorTag(target, color));
				return;
			}
		}

		// Rechtermuisklik op het teleport-item zelf (elke lading, bijv. Games necklace(1) t/m (8)).
		boolean isTeleportItem = t.getKind() == TeleportOption.Kind.FREE
			? t.getMenuTarget() != null && target.equalsIgnoreCase(t.getMenuTarget())
			: matchesItem(t, target);
		if (!isTeleportItem)
		{
			return;
		}
		String lower = option.toLowerCase(Locale.ROOT);
		for (String wanted : t.getMenuOptions())
		{
			if (lower.contains(wanted.toLowerCase(Locale.ROOT)))
			{
				entry.setOption(ColorUtil.wrapWithColorTag(option, color));
				return;
			}
		}
	}

	/** Hoort deze itemnaam bij de teleport (patronen als "Games necklace(" matchen elke lading)? */
	private static boolean matchesItem(TeleportOption t, String itemName)
	{
		String name = itemName.toLowerCase(Locale.ROOT).trim();
		for (String pattern : t.getItemPatterns())
		{
			String p = pattern.toLowerCase(Locale.ROOT);
			boolean prefix = p.endsWith("(") || p.endsWith("*");
			if (p.endsWith("*"))
			{
				p = p.substring(0, p.length() - 1);
			}
			if (prefix ? name.startsWith(p) : name.equals(p))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Komt een tekst uit een venster overeen met de gewenste keuze?
	 * Werkt ook met nummers of kleine toevoegingen: "2: Xeric's Glade", "2 Xeric's Glade", "Burthorpe."
	 */
	static boolean matchesChoice(String text, String wanted)
	{
		if (text == null)
		{
			return false;
		}
		String clean = Text.removeTags(text).trim().toLowerCase(Locale.ROOT);
		String w = wanted.toLowerCase(Locale.ROOT);
		return clean.contains(w) && clean.length() <= w.length() + 8;
	}

	/** Is dit item het teleport-item van de huidige stap (elke lading)? */
	boolean isCurrentTeleportItem(int itemId)
	{
		FarmPlan.Step step = getCurrentStep();
		if (step == null || step.getTeleportOption() == null
			|| step.getTeleportOption().getKind() != TeleportOption.Kind.ITEM)
		{
			return false;
		}
		return matchesItem(step.getTeleportOption(), itemManager.getItemComposition(itemId).getName());
	}

	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		// Dialoog/venster-opties zoeken, ongeveer 4x per seconde.
		if (++tickCounter % 10 != 0)
		{
			return;
		}
		FarmPlan.Step step = getCurrentStep();
		if (!config.highlightTeleport() || step == null || step.getTeleportOption() == null)
		{
			highlightedWidgets = Collections.emptyList();
			return;
		}
		TeleportOption t = step.getTeleportOption();
		if (t.getDialogOptions().isEmpty() && t.getSpellName() == null)
		{
			highlightedWidgets = Collections.emptyList();
			return;
		}
		List<Widget> found = new ArrayList<>();
		Widget[] roots = client.getWidgetRoots();
		if (roots != null)
		{
			for (Widget root : roots)
			{
				findWidgets(root, t, found, 0);
			}
		}
		highlightedWidgets = found;
	}

	private void findWidgets(Widget w, TeleportOption t, List<Widget> found, int depth)
	{
		if (w == null || w.isHidden() || depth > 25)
		{
			return;
		}
		// Keuzes staan soms in de tekst ("1: Tree Gnome Village") en soms in de naam van een knop.
		for (String wanted : t.getDialogOptions())
		{
			if (matchesChoice(w.getText(), wanted) || matchesChoice(w.getName(), wanted))
			{
				found.add(w);
				break;
			}
		}
		if (t.getSpellName() != null)
		{
			String name = w.getName();
			if (name != null && Text.removeTags(name).equalsIgnoreCase(t.getSpellName()))
			{
				found.add(w);
			}
		}
		findAll(w.getStaticChildren(), t, found, depth);
		findAll(w.getDynamicChildren(), t, found, depth);
		findAll(w.getNestedChildren(), t, found, depth);
	}

	private void findAll(Widget[] children, TeleportOption t, List<Widget> found, int depth)
	{
		if (children == null)
		{
			return;
		}
		for (Widget c : children)
		{
			findWidgets(c, t, found, depth + 1);
		}
	}

	List<Widget> getHighlightedWidgets()
	{
		return highlightedWidgets;
	}

	// ------------------------------------------------------------------ bank highlight

	/** Items die in de bank gemarkeerd worden: alles van het plan. */
	Set<Integer> getBankHighlightIds()
	{
		FarmPlan current = plan;
		return current == null ? Collections.emptySet() : current.getHighlightIds();
	}

	/** Items die in je inventory gemarkeerd worden: teleport en zaad van de huidige stap. */
	Set<Integer> getInventoryHighlightIds()
	{
		FarmPlan.Step step = getCurrentStep();
		if (step == null)
		{
			return Collections.emptySet();
		}
		Set<Integer> ids = new HashSet<>();
		if (step.getTeleportItemId() > 0)
		{
			ids.add(step.getTeleportItemId());
		}
		if (step.getSeedItemId() > 0)
		{
			ids.add(step.getSeedItemId());
		}
		return ids;
	}

	FarmPlannerConfig getConfig()
	{
		return config;
	}

	private static BufferedImage createIcon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(110, 70, 35));
		g.fillRect(7, 9, 2, 6);
		g.setColor(new Color(60, 170, 70));
		g.fillOval(2, 1, 12, 10);
		g.setColor(new Color(120, 220, 110));
		g.fillOval(4, 3, 5, 4);
		g.dispose();
		return img;
	}
}

package com.farmplanner;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Alle items die je hebt (bank + inventory + equipment), opgezocht op naam.
 */
public final class OwnedItems
{
	public static final class Entry
	{
		private final int id;
		private final String name;
		private int quantity;

		Entry(int id, String name, int quantity)
		{
			this.id = id;
			this.name = name;
			this.quantity = quantity;
		}

		public int getId()
		{
			return id;
		}

		public String getName()
		{
			return name;
		}

		public int getQuantity()
		{
			return quantity;
		}
	}

	private final Map<String, Entry> byName = new LinkedHashMap<>();

	public void add(int id, String name, int quantity)
	{
		if (name == null || quantity <= 0)
		{
			return;
		}
		String key = name.toLowerCase(Locale.ROOT);
		Entry existing = byName.get(key);
		if (existing != null)
		{
			existing.quantity += quantity;
		}
		else
		{
			byName.put(key, new Entry(id, name, quantity));
		}
	}

	public boolean isEmpty()
	{
		return byName.isEmpty();
	}

	public int size()
	{
		return byName.size();
	}

	/** Aantal van een item met exact deze naam. */
	public int count(String exactName)
	{
		Entry e = byName.get(exactName.toLowerCase(Locale.ROOT));
		return e == null ? 0 : e.quantity;
	}

	public Entry get(String exactName)
	{
		return byName.get(exactName.toLowerCase(Locale.ROOT));
	}

	/**
	 * Zoekt een item. Patronen die eindigen op "(" of "*" matchen op het begin van de naam.
	 * Bij meerdere matches wint degene met het hoogste aantal.
	 */
	public Entry find(String pattern)
	{
		String p = pattern.toLowerCase(Locale.ROOT);
		boolean prefix = p.endsWith("(") || p.endsWith("*");
		if (!prefix)
		{
			return byName.get(p);
		}
		if (p.endsWith("*"))
		{
			p = p.substring(0, p.length() - 1);
		}
		Entry best = null;
		for (Map.Entry<String, Entry> e : byName.entrySet())
		{
			if (e.getKey().startsWith(p) && (best == null || e.getValue().quantity > best.quantity))
			{
				best = e.getValue();
			}
		}
		return best;
	}

	/** Diepe kopie zodat de planner aantallen kan aftrekken. */
	public OwnedItems copy()
	{
		OwnedItems c = new OwnedItems();
		for (Entry e : byName.values())
		{
			c.add(e.id, e.name, e.quantity);
		}
		return c;
	}

	/** Trekt een aantal af (voor zaden, tablets, runes die opgaan). */
	void use(String exactName, int amount)
	{
		Entry e = get(exactName);
		if (e != null)
		{
			e.quantity = Math.max(0, e.quantity - amount);
		}
	}
}

package com.farmplanner;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.Predicate;

/**
 * Farming patches. De volgorde binnen elke run is de route-volgorde.
 */
public enum Patch
{
	// ---- Herb run ----
	ARDOUGNE_HERB(RunType.HERB, "Ardougne", 1, "Patch ten noorden van Ardougne.", Teleports.ARDOUGNE),
	CATHERBY_HERB(RunType.HERB, "Catherby", 1, "Patch ten westen van de bank, aan het strand.", Teleports.CATHERBY),
	FALADOR_HERB(RunType.HERB, "Falador", 1, "Patch ten zuiden van Falador (bij de cabbage patch).", Teleports.FALADOR_HERB),
	MORYTANIA_HERB(RunType.HERB, "Port Phasmatys", 1, "Loop vanaf de Ectofuntus naar het westen.", Teleports.MORYTANIA),
	HOSIDIUS_HERB(RunType.HERB, "Hosidius", 1, "Patch ten zuiden van Hosidius.", Teleports.HOSIDIUS),
	GUILD_HERB(RunType.HERB, "Farming Guild", 65, "Herb patch in de Farming Guild (65 Farming).", Teleports.FARMING_GUILD),
	TROLLHEIM_HERB(RunType.HERB, "Trollheim", 1, "Disease-vrije patch (My Arm's Big Adventure nodig).", Teleports.TROLLHEIM,
		PlanOptions::isIncludeTrollheim),

	// ---- Tree run ----
	LUMBRIDGE_TREE(RunType.TREE, "Lumbridge", 1, "Ten westen van het kasteel.", Teleports.LUMBRIDGE),
	VARROCK_TREE(RunType.TREE, "Varrock", 1, "Bij het kasteel, ten noordoosten van de fontein.", Teleports.VARROCK),
	FALADOR_TREE(RunType.TREE, "Falador", 1, "In het Falador park.", Teleports.FALADOR),
	TAVERLEY_TREE(RunType.TREE, "Taverley", 1, "Ten zuiden van Taverley.", Teleports.TAVERLEY),
	GNOME_TREE(RunType.TREE, "Tree Gnome Stronghold", 1, "Ten zuiden van de Grand Tree.", Teleports.GNOME_STRONGHOLD),
	GUILD_TREE(RunType.TREE, "Farming Guild", 65, "Tree patch in de Farming Guild (65 Farming).", Teleports.FARMING_GUILD),

	// ---- Fruit tree run ----
	GNOME_FRUIT(RunType.FRUIT_TREE, "Tree Gnome Stronghold", 1, "Ten oosten van de Grand Tree.", Teleports.GNOME_STRONGHOLD),
	VILLAGE_FRUIT(RunType.FRUIT_TREE, "Tree Gnome Village", 1, "Bij de spirit tree in Tree Gnome Village.", Teleports.SPIRIT_TREE_VILLAGE),
	CATHERBY_FRUIT(RunType.FRUIT_TREE, "Catherby", 1, "Aan de oostkant van Catherby, bij het strand.", Teleports.CATHERBY),
	BRIMHAVEN_FRUIT(RunType.FRUIT_TREE, "Brimhaven", 1, "Vanaf Ardougne de boot naar Brimhaven (30 coins).", Teleports.ARDOUGNE),
	LLETYA_FRUIT(RunType.FRUIT_TREE, "Lletya", 1, "Mourning's End Part I nodig.", Teleports.LLETYA,
		PlanOptions::isIncludeLletya),
	GUILD_FRUIT(RunType.FRUIT_TREE, "Farming Guild", 85, "Fruit tree patch in de Farming Guild (85 Farming).", Teleports.FARMING_GUILD);

	private final RunType runType;
	private final String location;
	private final int farmingLevel;
	private final String tip;
	private final List<TeleportOption> teleports;
	private final Predicate<PlanOptions> enabled;

	Patch(RunType runType, String location, int farmingLevel, String tip, TeleportOption[] teleports)
	{
		this(runType, location, farmingLevel, tip, teleports, o -> true);
	}

	Patch(RunType runType, String location, int farmingLevel, String tip, TeleportOption[] teleports,
		Predicate<PlanOptions> enabled)
	{
		this.runType = runType;
		this.location = location;
		this.farmingLevel = farmingLevel;
		this.tip = tip;
		this.teleports = Arrays.asList(teleports);
		this.enabled = enabled;
	}

	public RunType getRunType()
	{
		return runType;
	}

	public String getLocation()
	{
		return location;
	}

	public int getFarmingLevel()
	{
		return farmingLevel;
	}

	public String getTip()
	{
		return tip;
	}

	public List<TeleportOption> getTeleports()
	{
		return teleports;
	}

	public boolean isEnabled(PlanOptions options)
	{
		return enabled.test(options);
	}

	/** Patches voor deze run, in route-volgorde. */
	public static List<Patch> forRun(RunType type)
	{
		List<Patch> result = new ArrayList<>();
		for (Patch p : values())
		{
			if (p.runType == type)
			{
				result.add(p);
			}
		}
		return result;
	}
}

package com.farmplanner;

import java.util.Set;
import net.runelite.api.gameval.ObjectID;

/**
 * Object-ID's van de farming patches.
 */
final class PatchIds
{
	private PatchIds()
	{
	}

	static final Set<Integer> HERB = Set.of(
		ObjectID.FARMING_HERB_PATCH_1,
		ObjectID.FARMING_HERB_PATCH_2,
		ObjectID.FARMING_HERB_PATCH_3,
		ObjectID.FARMING_HERB_PATCH_4,
		ObjectID.FARMING_HERB_PATCH_5,
		ObjectID.MYARM_HERBPATCH,       // Trollheim
		ObjectID.FARMING_HERB_PATCH_6,  // Hosidius
		ObjectID.FARMING_HERB_PATCH_7,  // Farming Guild
		ObjectID.FARMING_HERB_PATCH_8
	);

	static final Set<Integer> TREE = Set.of(
		ObjectID.FARMING_TREE_PATCH_1,
		ObjectID.FARMING_TREE_PATCH_2,
		ObjectID.FARMING_TREE_PATCH_3,
		ObjectID.FARMING_TREE_PATCH_4,
		ObjectID.FARMING_TREE_PATCH_5,  // Lumbridge
		ObjectID.FARMING_TREE_PATCH_6,  // Farming Guild
		ObjectID.FARMING_TREE_PATCH_7
	);

	static final Set<Integer> FRUIT_TREE = Set.of(
		ObjectID.FARMING_FRUIT_TREE_PATCH_1,
		ObjectID.FARMING_FRUIT_TREE_PATCH_2,
		ObjectID.FARMING_FRUIT_TREE_PATCH_3,
		ObjectID.FARMING_FRUIT_TREE_PATCH_4,
		ObjectID.FARMING_FRUIT_TREE_PATCH_5,  // Lletya
		ObjectID.FARMING_FRUIT_TREE_PATCH_6,  // Farming Guild
		ObjectID.FARMING_FRUIT_TREE_PATCH_7
	);

	static Set<Integer> forRun(RunType type)
	{
		switch (type)
		{
			case HERB:
				return HERB;
			case TREE:
				return TREE;
			default:
				return FRUIT_TREE;
		}
	}

	static boolean isAnyPatch(int id)
	{
		return HERB.contains(id) || TREE.contains(id) || FRUIT_TREE.contains(id);
	}
}

package com.farmplanner;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.GameObject;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/** Markeert de farming patches van je run in de wereld, met wat je moet planten. */
public class PatchOverlay extends Overlay
{
	private final FarmPlannerPlugin plugin;

	@Inject
	PatchOverlay(FarmPlannerPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		FarmPlan.Step step = plugin.getCurrentStep();
		if (!plugin.getConfig().highlightPatches() || step == null)
		{
			return null;
		}
		Color color = plugin.getConfig().highlightColor();
		Color fill = new Color(color.getRed(), color.getGreen(), color.getBlue(), 40);
		String label = "Plant: " + step.getSeed()
			+ (step.getCompost() != null ? " + " + step.getCompost() : "");

		for (GameObject patch : plugin.getVisiblePatches())
		{
			Shape shape = patch.getClickbox();
			if (shape == null)
			{
				shape = patch.getConvexHull();
			}
			if (shape != null)
			{
				OverlayUtil.renderPolygon(graphics, shape, color, fill, new BasicStroke(2));
			}
			Point text = patch.getCanvasTextLocation(graphics, label, 120);
			if (text != null)
			{
				OverlayUtil.renderTextLocation(graphics, text, label, color);
			}
		}
		return null;
	}
}

package com.farmplanner;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import java.util.Map;

/**
 * Maakt een farm run op basis van wat je hebt en je levels.
 * Puur Java (geen RuneLite-afhankelijkheden), zodat het los te testen is.
 */
public final class PlanBuilder
{
	private static final String[] COMPOST_BEST_FIRST = {"Ultracompost", "Supercompost", "Compost"};
	private static final String BOTTOMLESS = "Bottomless compost bucket";
	static final int BRIMHAVEN_BOAT_COINS = 30;

	private PlanBuilder()
	{
	}

	private static final class Chosen
	{
		final TeleportOption option;
		final OwnedItems.Entry item;

		Chosen(TeleportOption option, OwnedItems.Entry item)
		{
			this.option = option;
			this.item = item;
		}

		String describe()
		{
			return item != null ? option.getLabel() + " [" + item.getName() + "]" : option.getLabel();
		}
	}

	public static FarmPlan build(RunType type, OwnedItems owned, int farmingLevel, int magicLevel, PlanOptions options)
	{
		FarmPlan plan = new FarmPlan(type, farmingLevel);
		OwnedItems left = owned.copy();

		// 1. Zaden: hoogste level eerst, die je kunt planten en hebt.
		Deque<OwnedItems.Entry> seedQueue = new ArrayDeque<>();
		for (Seed seed : Seed.forRun(type))
		{
			OwnedItems.Entry e = left.get(seed.getItemName());
			if (e != null && e.getQuantity() > 0 && farmingLevel >= seed.getLevel())
			{
				seedQueue.add(e);
			}
		}
		if (seedQueue.isEmpty())
		{
			plan.warn("Geen " + (type == RunType.HERB ? "zaden" : "saplings")
				+ " gevonden die je met " + farmingLevel + " Farming kunt planten.");
		}

		boolean bottomless = left.count(BOTTOMLESS) > 0;

		// 2. Route langs de patches.
		for (Patch patch : Patch.forRun(type))
		{
			if (!patch.isEnabled(options) || farmingLevel < patch.getFarmingLevel())
			{
				continue;
			}

			OwnedItems.Entry seed = takeSeed(seedQueue, left, plan);
			if (seed == null)
			{
				plan.addStep(new FarmPlan.Step(patch, null, null, null));
				continue;
			}

			Chosen teleport = chooseTeleport(patch, left, magicLevel, options, plan);
			if (teleport == null)
			{
				plan.warn("Geen teleport gevonden voor " + patch.getLocation() + " - je moet er naartoe lopen.");
			}

			String compost = takeCompost(left, bottomless, plan);
			FarmPlan.Step step = new FarmPlan.Step(patch, teleport == null ? null : teleport.describe(), seed.getName(), compost)
				.withSeedId(seed.getId());
			if (teleport != null)
			{
				step.withTeleport(teleport.option, teleport.item);
			}

			Seed seedDef = Seed.byItemName(seed.getName());
			if (seedDef != null)
			{
				plan.addXp(seedDef.getXpPlant() + compostXp(compost), seedDef.getXpLater());
				if (options.isPayProtection())
				{
					takePayment(seedDef, patch, left, plan, step);
				}
			}
			plan.addStep(step);
		}

		addSeedOverview(type, owned, farmingLevel, plan);
		if (type != RunType.HERB)
		{
			addSaplingAdvice(type, owned, farmingLevel, plan);
		}

		if (plan.getPlantedCount() == 0)
		{
			return plan;
		}

		// 3. Gereedschap.
		addTools(type, owned, plan);

		// 4. Coins.
		addCoins(type, owned, plan, options);

		if (type != RunType.HERB)
		{
			plan.tip("Geef de betaling aan de gardener bij de patch (Pay) - dan kan je boom niet doodgaan. "
				+ "Genoteerde items (noted) worden ook geaccepteerd.");
		}
		else
		{
			plan.tip("Vergeet niet je herbs te oogsten voordat je opnieuw plant.");
		}
		plan.tip("Zaden in de Seed vault van de Farming Guild worden niet meegeteld.");
		return plan;
	}

	static double compostXp(String compost)
	{
		if (compost == null)
		{
			return 0;
		}
		switch (compost)
		{
			case "Compost":
				return 18;
			case "Supercompost":
				return 26;
			default:
				return 36; // Ultracompost / Bottomless compost bucket (meestal ultra)
		}
	}

	private static void takePayment(Seed seed, Patch patch, OwnedItems left, FarmPlan plan, FarmPlan.Step step)
	{
		if (seed.getPaymentItem() == null)
		{
			return;
		}
		OwnedItems.Entry pay = left.get(seed.getPaymentItem());
		if (pay != null && pay.getQuantity() >= seed.getPaymentQty())
		{
			left.use(pay.getName(), seed.getPaymentQty());
			plan.withdraw(pay, seed.getPaymentQty());
			step.setPayment(seed.getPaymentLabel());
		}
		else
		{
			plan.warn("Geen bescherming voor " + seed.getItemName().replace(" sapling", "") + " in "
				+ patch.getLocation() + ": je mist " + seed.getPaymentLabel() + " (" + seed.getPaymentItem() + ").");
		}
	}

	private static String xp(double value)
	{
		return String.format(java.util.Locale.forLanguageTag("nl"), "%,.0f", value);
	}

	private static String treeName(Seed s)
	{
		return s.getItemName().replace(" sapling", "");
	}

	/** Overzicht van je zaden/saplings: hoeveel runs je ermee kunt. */
	private static void addSeedOverview(RunType type, OwnedItems owned, int farmingLevel, FarmPlan plan)
	{
		List<String> out = plan.getSeedOverview();
		int patches = plan.getSteps().size();
		int usable = 0;
		Seed bestUsed = null;
		for (Seed s : Seed.forRun(type))
		{
			int n = owned.count(s.getItemName());
			if (n <= 0)
			{
				continue;
			}
			if (farmingLevel < s.getLevel())
			{
				out.add(n + " x " + s.getItemName() + " - nog niet te planten (level " + s.getLevel() + ")");
				continue;
			}
			usable += n;
			if (bestUsed == null)
			{
				bestUsed = s;
			}
			String runs = patches > 0 ? " - genoeg voor " + (n / patches) + " volle run(s)" : "";
			out.add(n + " x " + s.getItemName() + " (" + xp(s.getXpTotal()) + " XP per patch)" + runs);
		}

		if (type != RunType.HERB)
		{
			for (Seed s : Seed.forRun(type))
			{
				int seeds = owned.count(s.getTreeSeedName());
				int seedlings = owned.count(s.getSeedlingName()) + owned.count(s.getSeedlingName() + " (w)");
				if (seeds > 0)
				{
					out.add(seeds + " x " + s.getTreeSeedName() + " - nog geen sapling (zie Saplings maken)");
				}
				if (seedlings > 0)
				{
					out.add(seedlings + " x " + s.getSeedlingName() + " - groeit nog (geef water als hij droog is)");
				}
				// Betere zaden die nog geen sapling zijn: tip om die eerst te maken
				if (seeds > 0 && farmingLevel >= s.getLevel() && (bestUsed == null || s.getLevel() > bestUsed.getLevel()))
				{
					plan.tip("Maak eerst saplings van je " + s.getTreeSeedName() + "s - " + treeName(s)
						+ " geeft meer XP dan " + (bestUsed == null ? "niets planten" : treeName(bestUsed)) + ".");
				}
			}
		}

		if (patches > 0 && usable > 0 && usable < patches)
		{
			out.add("Je hebt " + usable + " te planten voor " + patches + " patches.");
		}
		if (usable > 0)
		{
			out.add("De planner plant de hoogste (meeste XP) eerst; de rest blijft in je bank voor de volgende run.");
		}
	}

	/** Uitleg en advies om saplings te maken van boomzaden. */
	private static void addSaplingAdvice(RunType type, OwnedItems owned, int farmingLevel, FarmPlan plan)
	{
		List<String> out = plan.getSaplingAdvice();

		Seed best = null;
		for (Seed s : Seed.forRun(type))
		{
			if (farmingLevel >= s.getLevel())
			{
				best = s;
				break;
			}
		}
		if (best == null)
		{
			out.add("Je hebt nog niet genoeg Farming voor een " + (type == RunType.TREE ? "boom" : "fruitboom") + ".");
			return;
		}
		out.add("Beste " + (type == RunType.TREE ? "boom" : "fruitboom") + " op jouw level: " + treeName(best)
			+ " (level " + best.getLevel() + ") - " + xp(best.getXpTotal()) + " XP per boom ("
			+ xp(best.getXpPlant()) + " planten + " + xp(best.getXpLater()) + " check-health).");

		int totalSeeds = 0;
		for (Seed s : Seed.forRun(type))
		{
			int seeds = owned.count(s.getTreeSeedName());
			if (seeds <= 0 || farmingLevel < s.getLevel())
			{
				continue;
			}
			totalSeeds += seeds;
			out.add("Je kunt maken: " + seeds + " x " + s.getItemName() + " van je " + s.getTreeSeedName()
				+ "s (" + xp(seeds * s.getXpTotal()) + " XP).");
		}
		if (owned.count(best.getTreeSeedName()) == 0 && owned.count(best.getItemName()) == 0)
		{
			out.add("Je hebt geen " + best.getTreeSeedName() + "s. Die krijg je van o.a. bird nests, "
				+ "Master Farmers en de Grand Exchange.");
		}

		if (totalSeeds > 0)
		{
			int pots = owned.count("Plant pot");
			boolean trowel = owned.count("Gardening trowel") > 0;
			boolean can = owned.find("Watering can(") != null || owned.count("Gricoller's can") > 0;
			out.add("Nodig: " + totalSeeds + " gevulde Plant pots (je hebt er " + pots + ")"
				+ ", Gardening trowel " + (trowel ? "(heb je)" : "(mist)")
				+ ", Watering can " + (can ? "(heb je)" : "(mist)") + ".");
		}

		out.add("Hoe maak je een sapling:");
		out.add("1. Vul een Empty plant pot met aarde: gebruik hem op een lege patch met een Gardening trowel "
			+ "in je inventory (of koop gevulde Plant pots bij een farming-winkel).");
		out.add("2. Gebruik het boomzaad op de gevulde Plant pot (trowel in je inventory) -> seedling.");
		out.add("3. Geef de seedling water met een Watering can.");
		out.add("4. Na een paar minuten (in je inventory of bank) wordt het een sapling.");
	}

	/** Berekent hoeveel coins je nodig hebt en zet ze op de lijst. */
	static int coinsNeeded(RunType type, FarmPlan plan, PlanOptions options)
	{
		int coins = 0;
		for (FarmPlan.Step s : plan.getActiveSteps())
		{
			if (type != RunType.HERB)
			{
				coins += options.getCoinsPerTree();
			}
			if (s.getPatch() == Patch.BRIMHAVEN_FRUIT)
			{
				coins += BRIMHAVEN_BOAT_COINS;
			}
		}
		return coins;
	}

	private static void addCoins(RunType type, OwnedItems owned, FarmPlan plan, PlanOptions options)
	{
		int needed = coinsNeeded(type, plan, options);
		if (needed <= 0)
		{
			return;
		}
		OwnedItems.Entry coins = owned.get("Coins");
		int have = coins == null ? 0 : coins.getQuantity();
		if (have >= needed)
		{
			plan.withdraw(coins, needed);
		}
		else
		{
			if (coins != null)
			{
				plan.withdraw(coins, have);
			}
			plan.warn("Je hebt " + needed + " coins nodig, maar hebt er maar " + have + ".");
		}
		if (type != RunType.HERB)
		{
			plan.tip(options.getCoinsPerTree() + " coins per boom zodat de gardener je oude boom weghaalt.");
		}
	}

	private static OwnedItems.Entry takeSeed(Deque<OwnedItems.Entry> queue, OwnedItems left, FarmPlan plan)
	{
		while (!queue.isEmpty())
		{
			OwnedItems.Entry e = queue.peek();
			if (e.getQuantity() > 0)
			{
				left.use(e.getName(), 1);
				plan.withdraw(e, 1);
				return e;
			}
			queue.poll();
		}
		return null;
	}

	private static Chosen chooseTeleport(Patch patch, OwnedItems left, int magicLevel, PlanOptions options, FarmPlan plan)
	{
		for (TeleportOption opt : patch.getTeleports())
		{
			if (!opt.isEnabled(options))
			{
				continue;
			}
			switch (opt.getKind())
			{
				case FREE:
					return new Chosen(opt, null);

				case ITEM:
					for (String pattern : opt.getItemPatterns())
					{
						OwnedItems.Entry e = left.find(pattern);
						if (e != null && e.getQuantity() > 0)
						{
							if (opt.isConsumable())
							{
								left.use(e.getName(), 1);
								plan.withdraw(e, 1);
							}
							else
							{
								plan.withdrawOnce(e);
							}
							return new Chosen(opt, e);
						}
					}
					break;

				case SPELL:
					if (magicLevel >= opt.getMagicLevel() && hasRunes(left, opt.getRunes()))
					{
						for (Map.Entry<String, Integer> r : opt.getRunes().entrySet())
						{
							OwnedItems.Entry rune = left.get(r.getKey());
							left.use(r.getKey(), r.getValue());
							plan.withdraw(rune, r.getValue());
						}
						return new Chosen(opt, null);
					}
					break;
			}
		}
		return null;
	}

	private static boolean hasRunes(OwnedItems left, Map<String, Integer> runes)
	{
		for (Map.Entry<String, Integer> r : runes.entrySet())
		{
			if (left.count(r.getKey()) < r.getValue())
			{
				return false;
			}
		}
		return true;
	}

	private static String takeCompost(OwnedItems left, boolean bottomless, FarmPlan plan)
	{
		if (bottomless)
		{
			plan.withdrawOnce(left.get(BOTTOMLESS));
			return BOTTOMLESS;
		}
		for (String name : COMPOST_BEST_FIRST)
		{
			OwnedItems.Entry e = left.get(name);
			if (e != null && e.getQuantity() > 0)
			{
				left.use(name, 1);
				plan.withdraw(e, 1);
				return name;
			}
		}
		plan.warn("Niet genoeg compost voor alle patches.");
		return null;
	}

	private static void addTools(RunType type, OwnedItems owned, FarmPlan plan)
	{
		List<String> needed = type == RunType.HERB
			? List.of("Rake", "Seed dibber", "Spade")
			: List.of("Rake", "Spade");
		for (String tool : needed)
		{
			OwnedItems.Entry e = owned.get(tool);
			if (e != null)
			{
				plan.withdrawOnce(e);
			}
			else
			{
				plan.warn(tool + " niet gevonden - misschien ligt hij bij de Tool Leprechaun.");
			}
		}
		if (type != RunType.TREE)
		{
			OwnedItems.Entry secateurs = owned.get("Magic secateurs");
			if (secateurs != null)
			{
				plan.withdrawOnce(secateurs);
			}
		}
	}
}

